#!/usr/bin/env bash
# apply_chart_stage1.sh
# U-CHART-STAGE1-20260726 -- TradingView Lightweight Charts page, Stage 1.
# Repo: clawtrader-landing (Vercel, static site, NO CodeRabbit -- direct-to-main
# per established convention for this repo, per progress-tracker.md).
#
# Adds:
#   chart.html      -- new, annotated chart page (Entry/SL/TP price lines)
#   api/klines.js    -- new, Vercel serverless fn proxying Bybit kline (CORS dodge)
#   vercel.json      -- edited, adds /chart/:symbol rewrite (backed up first)
#
# Usage:
#   cd /Users/alex/Desktop/my-ai-assistant/clawtrader-landing
#   bash apply_chart_stage1.sh           # DRYRUN (default) -- shows what would happen
#   APPLY=1 bash apply_chart_stage1.sh   # actually writes

set -euo pipefail

DRYRUN=1
if [[ "${APPLY:-0}" == "1" ]]; then
  DRYRUN=0
fi

TS=$(date +%Y%m%d_%H%M%S)

CHART_B64=""
KLINES_B64=""
VERCEL_B64=""

write_new() {
  local path="$1"
  local b64="$2"
  if [[ -f "$path" ]]; then
    echo "SKIP (already exists, not overwriting): $path"
    return 0
  fi
  if [[ "$DRYRUN" == "1" ]]; then
    echo "DRYRUN would create: $path"
    return 0
  fi
  mkdir -p "$(dirname "$path")"
  echo "$b64" | base64 -d > "$path"
  echo "CREATED: $path"
}

replace_existing() {
  local path="$1"
  local b64="$2"
  if [[ ! -f "$path" ]]; then
    echo "ERROR: expected existing file not found: $path" >&2
    exit 1
  fi
  if echo "$b64" | base64 -d | cmp -s - "$path"; then
    echo "SKIP (already matches target content): $path"
    return 0
  fi
  if [[ "$DRYRUN" == "1" ]]; then
    echo "DRYRUN would backup + replace: $path"
    return 0
  fi
  cp "$path" "${path}.bak.pre-u-chart-stage1-${TS}"
  echo "$b64" | base64 -d > "$path.new"

  if ! python3 -c "import json; json.load(open('$path.new'))" 2>/tmp/vercel_json_err; then
    echo "ABORT: new vercel.json is not valid JSON:" >&2
    cat /tmp/vercel_json_err >&2
    rm -f "$path.new"
    exit 1
  fi

  mv "$path.new" "$path"
  echo "REPLACED (backup at ${path}.bak.pre-u-chart-stage1-${TS}): $path"
}

echo "== $([[ $DRYRUN == 1 ]] && echo DRYRUN || echo APPLY) =="

write_new "chart.html" "$CHART_B64"
write_new "api/klines.js" "$KLINES_B64"
replace_existing "vercel.json" "$VERCEL_B64"

if [[ "$DRYRUN" == "0" ]]; then
  echo "---"
  echo "Syntax check: api/klines.js"
  if command -v node >/dev/null 2>&1; then
    node --check api/klines.js && echo "OK: api/klines.js syntax valid"
  else
    echo "node not found locally -- syntax will be validated by Vercel at deploy time"
  fi
  echo "Syntax check: vercel.json"
  python3 -c "import json; json.load(open('vercel.json')); print('OK: vercel.json valid JSON')"
  echo "---"
  echo "Done. Review with: git status && git diff --stat"
fi
